export function updateCamera(project,state,dt){const settings=project.camera;if(settings?.mode!=='follow')return;const target=state.objects.find(o=>o.id===settings.targetId)||state.objects.find(o=>o.type==='player');if(!target)return;const desired={x:target.x+target.w/2,y:target.y+target.h/2};state.cameraCenter??={...desired};const factor=1-Math.exp(-Math.max(1,settings.smoothing||8)*Math.max(0,dt));state.cameraCenter.x+=(desired.x-state.cameraCenter.x)*factor;state.cameraCenter.y+=(desired.y-state.cameraCenter.y)*factor}
export function cameraBounds(project,state){const width=project.width||960,height=project.height||540;if(!state)return{x:0,y:0,w:width,h:height};const settings=project.camera||{};if(settings.useSceneCamera!==false){const camera=state.objects.find(o=>o.type==='camera');if(camera)return{x:camera.x,y:camera.y,w:camera.w,h:camera.h}}
 const zoom=Math.max(1,Math.min(4,Number(settings.zoom)||1)),w=width/zoom,h=height/zoom,target=state.objects.find(o=>o.id===settings.targetId)||state.objects.find(o=>o.type==='player'),center=settings.mode==='follow'?(state.cameraCenter||{x:(target?.x||0)+(target?.w||0)/2,y:(target?.y||0)+(target?.h||0)/2}):{x:width/2,y:height/2};return{x:Math.max(0,Math.min(width-w,center.x-w/2)),y:Math.max(0,Math.min(height-h,center.y-h/2)),w,h}}
